import numpy as np
def unit(ra, dec):
    ra, dec = np.radians(ra), np.radians(dec)
    return np.array([np.cos(dec) * np.cos(ra), np.cos(dec) * np.sin(ra), np.sin(dec)])
a, b = unit(359.9999, 28.0), unit(0.0001, 28.0)
print(round(abs(359.9999 - 0.0001), 4), round(float(np.linalg.norm(a - b)) * 206264.806, 3))

