import numpy as np
G = 4 * np.pi ** 2
acc = lambda r: -G * r / np.linalg.norm(r) ** 3
energy = lambda r, v: 0.5 * v @ v - G / np.linalg.norm(r)
for name in ("euler", "leapfrog"):
    r, v, dt = np.array([1.0, 0.0]), np.array([0.0, 2 * np.pi]), 0.001
    e0 = energy(r, v)
    for _ in range(1000):
        if name == "euler":
            r, v = r + v * dt, v + acc(r) * dt
        else:
            v = v + 0.5 * dt * acc(r); r = r + dt * v; v = v + 0.5 * dt * acc(r)
    print(name, f"{abs(energy(r, v) / e0 - 1):.3f}")
